package com.aiuml.architect.common;
import com.aiuml.architect.auth.AuthService; import com.aiuml.architect.project.ProjectService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestControllerAdvice class ApiExceptionHandler { @ExceptionHandler(NoSuchElementException.class) ResponseEntity<Map<String,String>> missing(NoSuchElementException e){return ResponseEntity.status(404).body(Map.of("message",e.getMessage()));} @ExceptionHandler(IllegalArgumentException.class) ResponseEntity<Map<String,String>> invalidDocument(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()));} @ExceptionHandler({ProjectService.AccessDeniedException.class,AuthService.InvalidCredentialsException.class}) ResponseEntity<Map<String,String>> unauthorized(RuntimeException e){return ResponseEntity.status(e instanceof AuthService.InvalidCredentialsException?401:403).body(Map.of("message",e instanceof AuthService.InvalidCredentialsException?"Invalid email or password":"Project membership required"));} }
